import{_ as a,o as t,c as s,a3 as n}from"./chunks/framework.DQ-7HQaQ.js";const h=JSON.parse('{"title":"From App Studio to your hosted RAG","description":"A gentle bridge from the current FastAPI template and Docker server to the original IS373 individual RAG requirements.","frontmatter":{"title":"From App Studio to your hosted RAG","description":"A gentle bridge from the current FastAPI template and Docker server to the original IS373 individual RAG requirements."},"headers":[],"relativePath":"students/from-app-studio.md","filePath":"students/from-app-studio.md","lastUpdated":1794433168000}'),r={name:"students/from-app-studio.md"};function o(i,e,p,c,d,l){return t(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="from-your-existing-fastapi-app-to-a-small-hosted-rag" tabindex="-1">From your existing FastAPI app to a small hosted RAG <a class="header-anchor" href="#from-your-existing-fastapi-app-to-a-small-hosted-rag" aria-label="Permalink to &quot;From your existing FastAPI app to a small hosted RAG&quot;">​</a></h1><p><strong>Do not rebuild your server or replace your existing app.</strong> <a href="https://github.com/kaw393939/is373-app-studio" target="_blank" rel="noreferrer">IS373 App Studio</a> teaches FastAPI, accounts and permissions; <a href="https://github.com/kaw393939/373_hosting" target="_blank" rel="noreferrer">Server Studio</a> covers Docker, Traefik and HTTPS. This walkthrough connects them to your <strong>own</strong> individual RAG project.</p><p>This is an optional pathway, not new Canvas work. See <a href="./embeddings">embeddings</a> for the numerical representations and <a href="./chunking">chunking</a> for source boundaries. A working hosted RAG demonstration still needs actual <strong>retrieval and model generation</strong>. The <a href="./reference">local retrieval lab</a> is preparation, not a submission. LangChain and similar <a href="./library-survey">libraries</a> are choices to research, not requirements.</p><h2 id="picture-the-smallest-complete-product" tabindex="-1">Picture the smallest complete product <a class="header-anchor" href="#picture-the-smallest-complete-product" aria-label="Permalink to &quot;Picture the smallest complete product&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Five permitted source documents</span></span>
<span class="line"><span>  → importer → source IDs + chunks (or sourced graph relationships)</span></span>
<span class="line"><span>  → persistent index</span></span>
<span class="line"><span>  → question in YOUR FastAPI app</span></span>
<span class="line"><span>  → real retrieval: source IDs and passages/paths</span></span>
<span class="line"><span>  → real model call with selected evidence</span></span>
<span class="line"><span>  → answer and openable source references</span></span></code></pre></div><p>If you choose vectors, use <strong>real compatible embeddings</strong> for both corpus and query. If you choose a graph, trace real relationships to original passages. You must research both approaches but implement only the one(s) you justify.</p><h2 id="checkpoint-1-—-understand-your-own-starting-point" tabindex="-1">Checkpoint 1 — Understand your own starting point <a class="header-anchor" href="#checkpoint-1-—-understand-your-own-starting-point" aria-label="Permalink to &quot;Checkpoint 1 — Understand your own starting point&quot;">​</a></h2><p>Open <strong>your student repository</strong>, not the instructor&#39;s template. Locate <code>app/main.py</code> and <code>create_app()</code>. Find the existing feature routers (<code>app/features/</code>), persistence/configuration, templates and tests. Identify your actual server URL and working Docker/HTTPS deployment. Don&#39;t alter accounts, roles, domains or unrelated services.</p><p><strong>Explain:</strong> Which function registers a route? Which part controls a database write? Which settings hold secrets? Bring one specific blocker to class, not a vague request to start everything over.</p><h2 id="checkpoint-2-—-trace-one-original-source" tabindex="-1">Checkpoint 2 — Trace one original source <a class="header-anchor" href="#checkpoint-2-—-trace-one-original-source" aria-label="Permalink to &quot;Checkpoint 2 — Trace one original source&quot;">​</a></h2><p>Choose one permitted short document and one useful question. Give the source a stable ID, title, origin, version/date and permission note. Prepare a chunk with a source location, or a graph entity/relationship that points back to an actual passage. First inspect this with the <a href="./reference#your-first-15-minutes">15-minute offline lab</a> if that helps.</p><p><strong>Check:</strong> Import the same data twice without duplicate records. Change a copied source and prove the updated representation can be found. Mark planned checks as planned until executed.</p><h2 id="checkpoint-3-—-add-one-narrow-retrieval-feature" tabindex="-1">Checkpoint 3 — Add one narrow retrieval feature <a class="header-anchor" href="#checkpoint-3-—-add-one-narrow-retrieval-feature" aria-label="Permalink to &quot;Checkpoint 3 — Add one narrow retrieval feature&quot;">​</a></h2><p>Ask your AI coding partner to help add a <strong>small feature router</strong> to your existing FastAPI app (for example, <code>app/features/rag.py</code>), with one <code>POST /api/rag/ask</code> route and separate import/retrieval/generation functions. These are example names, <strong>not</strong> required file or endpoint names.</p><p>Keep ingestion restricted to an authorized account or trusted CLI; don&#39;t expose arbitrary import to visitors. Retrieval should expose traceable evidence IDs in debug/test output. Start with a keyword baseline, then build the chosen <strong>real vector or graph retrieval</strong>. Don&#39;t send the entire document collection to a model and call that retrieval.</p><p><strong>Check:</strong> A question produces actual retrieved IDs/passages or graph paths; an unsupported question can be recognized. Run existing App Studio checks and add focused tests without weakening APP-001–003 behavior.</p><h2 id="checkpoint-4-—-generate-a-grounded-answer" tabindex="-1">Checkpoint 4 — Generate a grounded answer <a class="header-anchor" href="#checkpoint-4-—-generate-a-grounded-answer" aria-label="Permalink to &quot;Checkpoint 4 — Generate a grounded answer&quot;">​</a></h2><p>Use a model/provider you can actually access. Send only relevant <strong>authorized</strong> retrieved evidence to the model through server-side configuration. Keep provider credentials out of JavaScript, commits, screenshots and logs.</p><p>Display both the answer <strong>and independently openable references</strong>. Ask the model to abstain when evidence is missing, but don&#39;t trust the prompt alone: test an unanswerable question, inspect output and explain what remains uncertain.</p><p><strong>Check:</strong> Save the actual retrieval results, the redacted context supplied to the model, the actual model response, and which claims the cited sources support. Canned text is a UI mock, not completed RAG.</p><h2 id="checkpoint-5-—-deploy-the-same-app-you-tested" tabindex="-1">Checkpoint 5 — Deploy the same app you tested <a class="header-anchor" href="#checkpoint-5-—-deploy-the-same-app-you-tested" aria-label="Permalink to &quot;Checkpoint 5 — Deploy the same app you tested&quot;">​</a></h2><p>Reuse the existing student server and Docker/Traefik/HTTPS setup. Put persistent data in an appropriate Docker volume or other durable store. Keep database services private, restrict administrative routes, and bound usage/cost for a public demo. <strong>Don&#39;t change DNS or discard a working calculator service without checking first.</strong></p><p><strong>Check:</strong> Open the HTTPS app as a visitor, ask a supported and unsupported question, click a cited source, then restart the app and confirm the stored sources remain. Preserve the exact working source revision and a safe deployment procedure.</p><h2 id="what-to-show-in-class" tabindex="-1">What to show in class <a class="header-anchor" href="#what-to-show-in-class" aria-label="Permalink to &quot;What to show in class&quot;">​</a></h2><p>At <strong>Plan (Nov 17)</strong> bring the source plan, vector/graph comparison, a sketch and expected-evidence questions. A working RAG app is <strong>not required yet</strong>. At <strong>Build (Nov 24)</strong> demonstrate a <strong>small real hosted import → retrieval → generation journey</strong>. By <strong>Checked Release (Dec 3)</strong> improve persistence, source citations, repeatability and actual evaluation; by <strong>Improve (Dec 10)</strong> address real peer feedback. Follow Canvas for official deadlines.</p><h2 id="copyable-ai-coding-agent-request" tabindex="-1">Copyable AI coding-agent request <a class="header-anchor" href="#copyable-ai-coding-agent-request" aria-label="Permalink to &quot;Copyable AI coding-agent request&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>I&#39;m extending MY existing IS373 App Studio repo for the individual RAG</span></span>
<span class="line"><span>assignment. Read README.md, AGENTS.md, SPEC.md, app/main.py and the current</span></span>
<span class="line"><span>routers/settings/tests. First tell me what already works and ask me to</span></span>
<span class="line"><span>confirm my permitted corpus and model access. Do not edit yet.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>I need ONE small import → retrieval → model answer path with traceable</span></span>
<span class="line"><span>sources, using my existing FastAPI, auth, persistence and server setup.</span></span>
<span class="line"><span>Research vector and graph but implement only the justified choice.</span></span>
<span class="line"><span>Propose the next smallest issue, a 3–5-step plan and observable checks.</span></span>
<span class="line"><span>When I approve, make a bounded change and run REAL tests; don&#39;t claim a</span></span>
<span class="line"><span>mock is generation or a keyword baseline is a vector/graph system.</span></span>
<span class="line"><span>Never reset my app, server, database, DNS or permissions to make progress.</span></span>
<span class="line"><span>Show me code paths, actual outputs and one question to check my understanding.</span></span></code></pre></div><p>The <a href="https://github.com/kaw393939/is373-studio/blob/main/docs/projects/individual.md" target="_blank" rel="noreferrer">original assignment</a> is the grading authority. The goal is a result students can <strong>understand, defend and improve</strong>, not the largest framework.</p><p><a href="./">Back to student guide</a> · <a href="./library-survey">Library survey</a> · <a href="./prompts">AI coding prompts</a> · <a href="./check">Five evaluation questions</a></p>`,29)])])}const g=a(r,[["render",o]]);export{h as __pageData,g as default};
